{
  "tasks": [
    {
      "task_id": "T1",
      "title": "计算一组和三组响应分钟中位数并升序排名",
      "business_question": "只看一组与三组，计算各团队的响应分钟中位数，并按中位数升序排名。",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心问题（比较两组响应效率），直接支持业务目标中的排名决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "in",
                "value": [
                  "一组",
                  "三组"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0005",
                "alias": "response_minutes_median"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "response_minutes_median",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
